<script setup lang="ts">
const api=useApi(); const { data: invoices, refresh }=await useAsyncData('admin-invoices',()=>api.request<any[]>('/admin/invoices').catch(()=>[]))
async function refund(id:string){const amount=prompt('Refund amount (USD):'); if(!amount) return; const reason=prompt('Reason:')||'Admin refund'; await api.request(`/admin/invoices/${id}/refund`,{method:'POST',body:{amount:Number(amount),reason}}); await refresh()}
async function pdf(inv:any){await api.download(`/admin/invoices/${inv._id}/pdf`, `${inv.ref}.pdf`)}
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">Finance</p><h1 class="mt-1 font-display text-[clamp(2.2rem,3vw,2.7rem)] font-semibold tracking-[-.045em]">Invoices & payments.</h1><p class="mt-1 text-[11.5px] text-ink/45">Issued invoices, captured payments and refunds.</p></div><div class="a-card overflow-hidden"><table class="w-full text-left text-[11px]"><thead class="border-b border-ink/10 bg-paper"><tr class="font-mono text-[7.5px] uppercase tracking-[.08em] text-ink/35"><th class="px-4 py-2.5">Invoice</th><th class="px-4 py-2.5">Type</th><th class="px-4 py-2.5">Total</th><th class="px-4 py-2.5">Status</th><th class="px-4 py-2.5">Date</th><th class="px-4 py-2.5"></th></tr></thead><tbody><tr v-for="i in invoices" :key="i._id" class="border-t border-ink/10"><td class="px-4 py-3 font-mono text-[9px]">{{ i.ref }}</td><td class="px-4 py-3 capitalize">{{ String(i.type).replace('_',' ') }}</td><td class="px-4 py-3">{{ money(i.total) }}</td><td class="px-4 py-3"><StatusPill :status="i.status"/></td><td class="px-4 py-3 text-ink/40">{{ shortDate(i.createdAt) }}</td><td class="px-4 py-3"><div class="flex gap-2"><button class="text-[9px] font-semibold text-signal-deep" @click="pdf(i)">PDF</button><button v-if="i.status==='paid'" class="text-[9px] font-semibold text-ink/45" @click="refund(i._id)">Refund</button></div></td></tr></tbody></table></div></div></template>
